import org.apache.commons.lang.time.DurationFormatUtils;

public class Scratch {
    public static void main(String[] args) throws Exception {
        p("words(0,false,false)", DurationFormatUtils.formatDurationWords(0, false, false));
        p("words(0,true,true)", DurationFormatUtils.formatDurationWords(0, true, true));
        p("words(0,true,false)", DurationFormatUtils.formatDurationWords(0, true, false));
        p("words(0,false,true)", DurationFormatUtils.formatDurationWords(0, false, true));

        long oneDay = 24L*60*60*1000;
        long oneHour = 60L*60*1000;
        long oneMinute = 60L*1000;
        long oneSecond = 1000L;

        p("words(1 day,true,true)", DurationFormatUtils.formatDurationWords(oneDay, true, true));
        p("words(1 hour,true,true)", DurationFormatUtils.formatDurationWords(oneHour, true, true));
        p("words(1 minute,true,true)", DurationFormatUtils.formatDurationWords(oneMinute, true, true));
        p("words(1 second,true,true)", DurationFormatUtils.formatDurationWords(oneSecond, true, true));
        p("words(1 day 1 hour 1 min 1 sec,true,true)", DurationFormatUtils.formatDurationWords(oneDay+oneHour+oneMinute+oneSecond, true, true));
        p("words(1 day 1 hour 1 min 1 sec,false,false)", DurationFormatUtils.formatDurationWords(oneDay+oneHour+oneMinute+oneSecond, false, false));

        p("HMS(0)", DurationFormatUtils.formatDurationHMS(0));
        p("HMS(3723005)", DurationFormatUtils.formatDurationHMS(3723005));
        p("HMS(negative 5000)", DurationFormatUtils.formatDurationHMS(-5000));

        p("ISO(0)", DurationFormatUtils.formatDurationISO(0));
        p("ISO(3723005)", DurationFormatUtils.formatDurationISO(3723005));

        p("duration noPad", DurationFormatUtils.formatDuration(3723005, "H:m:s.S", false));
        p("duration pad", DurationFormatUtils.formatDuration(3723005, "HH:mm:ss.SSS", true));
        p("duration literal", DurationFormatUtils.formatDuration(5000, "'Duration: 's' sec'", true));

        try {
            DurationFormatUtils.formatDuration(1000, null);
            System.out.println("no exception for null format");
        } catch (Exception e) {
            System.out.println("null format -> " + e.getClass().getName());
        }

        try {
            DurationFormatUtils.formatPeriod(2000, 1000, "d");
            System.out.println("formatPeriod negative handled: " + DurationFormatUtils.formatPeriod(2000, 1000, "H:mm:ss.SSS"));
        } catch (Exception e) {
            System.out.println("negative period -> " + e.getClass().getName());
        }

        long day = 24L*60*60*1000;
        p("period 27 days", DurationFormatUtils.formatPeriod(0, 27*day, "d"));
        p("period 28 days", DurationFormatUtils.formatPeriod(0, 28*day, "d"));
        p("period 29 days", DurationFormatUtils.formatPeriod(0, 29*day, "d"));

        java.util.Calendar start = java.util.Calendar.getInstance(java.util.TimeZone.getTimeZone("GMT"));
        start.clear();
        start.set(2000, 0, 1, 0, 0, 0);
        java.util.Calendar end = java.util.Calendar.getInstance(java.util.TimeZone.getTimeZone("GMT"));
        end.clear();
        end.set(2003, 2, 15, 5, 30, 0);
        p("period years/months/days", DurationFormatUtils.formatPeriod(start.getTimeInMillis(), end.getTimeInMillis(), "y' years 'M' months 'd' days 'H' hours 'm' minutes 's' seconds'", true, java.util.TimeZone.getTimeZone("GMT")));

        p("periodISO", DurationFormatUtils.formatPeriodISO(start.getTimeInMillis(), end.getTimeInMillis()));
    }

    static void p(String label, String value) {
        System.out.println(label + " = [" + value + "]");
    }
}
